const menu=document.querySelector('.menu-toggle');
const nav=document.querySelector('#navigation');
function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.header'))closeMenu();});
matchMedia('(min-width:701px)').addEventListener('change',closeMenu);
const form=document.querySelector('#contact-form');const subject=document.querySelector('#subject');const city=document.querySelector('#city');const objective=document.querySelector('#objective');function summary(){return 'Assunto: '+subject.value+(city.value.trim()?'\nCidade da empresa: '+city.value.trim():'')+(objective.value.trim()?'\nEquipamento/necessidade: '+objective.value.trim():'');}function update(){document.querySelector('#message-preview').textContent=summary();}form.addEventListener('input',update);form.addEventListener('change',update);form.addEventListener('submit',e=>{e.preventDefault();window.open('https://wa.me/5547992185521?text='+encodeURIComponent('Olá, Manutech Industrial! Gostaria de consultar um serviço.\n\n'+summary()),'_blank','noopener');});document.querySelectorAll('[data-service]').forEach(button=>button.addEventListener('click',()=>{subject.value=button.dataset.service;update();document.querySelector('#contato').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});subject.focus({preventScroll:true});}));update();document.querySelectorAll('.filters button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filters button').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));let count=0;document.querySelectorAll('[data-category]').forEach(item=>{const show=button.dataset.filter==='todas'||item.dataset.category===button.dataset.filter;item.hidden=!show;if(show){count++;item.classList.remove('pending');}});document.querySelector('#filter-status').textContent=count+' referência'+(count===1?' exibida.':'s exibidas.');}));document.querySelectorAll('.faq details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.faq details').forEach(other=>{if(other!==d)other.open=false;});}));
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('pending');observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('[data-reveal]').forEach((element,index)=>{element.style.setProperty('--delay',`${index%3*65}ms`);element.classList.add('pending');observer.observe(element);});}
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('paused',document.hidden));
const floating=document.querySelector('.whatsapp');const protectedElements=[...document.querySelectorAll('h1,h2,h3,p,figcaption,.button,label,input,select,textarea,summary,.text-link,.phone,.email,.solution-cards button,.reference-list button,.footer-grid a, .footer-bottom a,.filters button,.header a,.menu-toggle')];let floatingFrame=false;
function placeFloating(){floating.classList.remove('is-hidden','on-left','raised');const rects=protectedElements.filter(e=>e.checkVisibility?e.checkVisibility():e.getClientRects().length>0).map(e=>e.getBoundingClientRect()).filter(r=>r.width>0&&r.height>0&&r.bottom>0&&r.top<innerHeight);const safe=()=>{const b=floating.getBoundingClientRect();return !rects.some(r=>r.left<b.right+6&&r.right>b.left-6&&r.top<b.bottom+6&&r.bottom>b.top-6);};let found=false;for(const size of[58,44]){Object.assign(floating.style,{width:size+'px',height:size+'px',minWidth:size+'px',minHeight:size+'px',padding:size===58?'15px':'9px'});for(let bottom=16;bottom<innerHeight-size-16&&!found;bottom+=14){for(const left of[false,true]){Object.assign(floating.style,{bottom:bottom+'px',left:left?'16px':'auto',right:left?'auto':'16px'});if(safe()){found=true;break;}}}if(found)break;}if(!found)Object.assign(floating.style,{bottom:'16px',left:'auto',right:'4px'});}
let floatingUntil=0;function floatingTick(){placeFloating();if(performance.now()<floatingUntil)requestAnimationFrame(floatingTick);else floatingFrame=false;}function queueFloating(){floatingUntil=performance.now()+1200;if(!floatingFrame){floatingFrame=true;requestAnimationFrame(floatingTick);}}
window.addEventListener('scroll',queueFloating,{passive:true});window.addEventListener('resize',queueFloating);document.fonts.ready.then(placeFloating);


setTimeout(placeFloating,1200);

document.addEventListener("toggle",queueFloating,true);
